//======================================================================
// Trend C10.3A - Deterministic Execution V1.0
//
// 基于：C10.3A
//
// 核心修改：
// 1. 所有趋势 / 因子 / 收盘确认信号，只在 OnBarClose 中计算
// 2. OnBarClose 不直接使用 Close 成交，只产生 Pending Signal
// 3. 所有 Close Confirmed Entry / Exit，在下一根 Bar 的 OnBarOpen 使用 Open 执行
// 4. Disaster Stop 保留在 OnBar，盘中立即生效
// 5. EntryBarIndex 记录真实执行 Bar，不再记录 Signal Bar
// 6. ATR / FailureLevel 在信号产生时冻结，防止下一 Bar 数据污染信号
// 7. Entry Stop 以实际执行 Bar Open 为锚
//======================================================================

Params
    Numeric Lots(1);
    Numeric SlowSlopeMin(0.05);

Vars
    Series<Numeric> FastMA;
    Series<Numeric> SlowMA;
    Series<Numeric> ATRValue;
    Series<Numeric> ATRBase50;
    Series<Numeric> VolRatio;
    Series<Numeric> EntryUpper55;
    Series<Numeric> EntryLower55;
    Series<Numeric> ExitUpper40;
    Series<Numeric> ExitLower40;
    Series<Numeric> LongBreakStrength;
    Series<Numeric> ShortBreakStrength;
    Series<Numeric> OneBarMove;
    Series<Numeric> PathMove20;
    Series<Numeric> LongER20;
    Series<Numeric> ShortER20;
    Series<Numeric> LongFastSlopeATR;
    Series<Numeric> ShortFastSlopeATR;
    Series<Numeric> LongSlowSlopeATR;
    Series<Numeric> ShortSlowSlopeATR;
    Series<Numeric> MASpreadATR;
    Global Numeric EntryBarIndex(0);
    Global Numeric LongFailureLevel(0);
    Global Numeric LongStopPrice(0);
    Global Bool ActionThisBar(False);
    Global Bool PendingLongEntry(False);
    Global Bool PendingLongExit(False);
    Global Numeric PendingLongATR(0);
    Global Numeric PendingLongFailureLevel(0);

Events
    OnBarOpen(ArrayRef<Integer> indexs)
    {
        ActionThisBar = False;
        If (PendingLongExit == True And MarketPosition == 1) {
            Sell(0, Open);
            ActionThisBar = True;
        } Else If (PendingLongEntry == True And MarketPosition == 0) {
            Buy(Lots, Open);
            EntryBarIndex = CurrentBar;
            LongFailureLevel = PendingLongFailureLevel;
            LongStopPrice = Open - 2.80 * PendingLongATR;
        }
    }

    OnBar(ArrayRef<Integer> indexs)
    {
        If (MarketPosition == 1 And ActionThisBar == False And LongStopPrice > 0 And Low <= LongStopPrice) {
            Sell(0, Min(Open, LongStopPrice));
            ActionThisBar = True;
        }
    }

    OnBarClose(ArrayRef<Integer> indexs)
    {
        FastMA = AverageFC(Close, 40);
        SlowMA = AverageFC(Close, 120);
        ATRValue = AvgTrueRange(20);
        EntryUpper55 = HighestFC(High[1], 55);
        ExitLower40 = LowestFC(Low[1], 40);

        LongBreakStrength = (Close - EntryUpper55) / ATRValue;
        LongER20 = (Close - Close[20]) / SummationFC(Abs(Close - Close[1]), 20);
        LongFastSlopeATR = (FastMA - FastMA[10]) / ATRValue;
        LongSlowSlopeATR = (SlowMA - SlowMA[20]) / ATRValue;
        MASpreadATR = Abs(FastMA - SlowMA) / ATRValue;

        If (MarketPosition == 1) {
            If (CurrentBar - EntryBarIndex <= 4 And Close < LongFailureLevel) {
                PendingLongExit = True;
            } Else If (Close < ExitLower40) {
                PendingLongExit = True;
            }
        } Else If (MarketPosition == 0) {
            If (FastMA > SlowMA And LongSlowSlopeATR >= SlowSlopeMin And Close > EntryUpper55 And LongBreakStrength >= 0.15 And LongER20 >= 0.20 And LongFastSlopeATR >= 0.25 And MASpreadATR >= 0.30) {
                PendingLongEntry = True;
                PendingLongATR = ATRValue;
                PendingLongFailureLevel = EntryUpper55 - 0.15 * ATRValue;
            }
        }
    }

