# Solana AI Quant - ZLEMA 零滞后趋势突破策略 (内置基准)
# 核心逻辑：
# 1. 计算快慢零滞后均线 (ZLEMA Fast 9, Slow 26) 与超趋势 SuperTrend
# 2. 快线上穿慢线且 SuperTrend 确认看多时，产生 BUY 信号并挂 ATR 止损
# 3. 实时执行 2.0 * ATR 灾难硬止损与 3.5 * ATR 目标止盈
# 4. SuperTrend 翻转向下时平仓离场
# ======================================================================
from typing import Optional, Dict, Any
import pandas as pd
from strategy import TradeSignal
from strategy_base import BaseStrategy
from config import StrategyConfig, SolanaFrictionConfig

class BuiltinZLEMAStrategy(BaseStrategy):
    """ZLEMA 双通道动量策略 (内置基准)"""
    def __init__(self, config: StrategyConfig = None, friction_config: SolanaFrictionConfig = None, **kwargs):
        super().__init__(config, friction_config)
        self.strategy_name = "ZLEMA 双通道动量策略 (内置基准)"
        self.fast_period = kwargs.get("fast_period", 9)
        self.slow_period = kwargs.get("slow_period", 26)
        self.atr_mult = kwargs.get("atr_mult", 2.0)

    def prepare_indicators(self, df: pd.DataFrame) -> pd.DataFrame:
        return super().prepare_indicators(df)

    def evaluate_bar(self, current_bar: pd.Series, current_position: Optional[Dict[str, Any]] = None, sol_price_usd: float = 140.0) -> TradeSignal:
        price = float(current_bar['close'])
        high = float(current_bar['high'])
        low = float(current_bar['low'])
        atr = float(current_bar.get('atr', price * 0.02))
        z_fast = float(current_bar.get('zlema_fast', price))
        z_slow = float(current_bar.get('zlema_slow', price))
        trend_dir = int(current_bar.get('trend_dir', 1))
        st_line = float(current_bar.get('supertrend', price))

        if current_position is not None and current_position.get('size', 0) > 0:
            entry_price = float(current_position['entry_price'])
            hard_stop = entry_price - (self.atr_mult * atr)
            take_profit = entry_price + (3.5 * atr)
            if low <= hard_stop:
                self.bars_since_last_exit = 0
                return TradeSignal(action='SELL', price=hard_stop, reason=f'硬止损触发: {low:.2f} <= {hard_stop:.2f}')
            if high >= take_profit:
                self.bars_since_last_exit = 0
                return TradeSignal(action='SELL', price=take_profit, reason=f'目标止盈达成: {high:.2f} >= {take_profit:.2f}')
            if trend_dir == -1:
                self.bars_since_last_exit = 0
                return TradeSignal(action='SELL', price=price, reason=f'超趋势翻转看跌离场: {price:.2f}')
            return TradeSignal(action='HOLD', price=price, trailing_stop=st_line, stop_loss=hard_stop, take_profit=take_profit)

        self.bars_since_last_exit += 1
        if self.bars_since_last_exit >= 3:
            if z_fast > z_slow and trend_dir == 1:
                stop_loss = price - (self.atr_mult * atr)
                take_profit = price + (3.5 * atr)
                return TradeSignal(action='BUY', price=price, stop_loss=stop_loss, take_profit=take_profit, reason='ZLEMA金叉且超趋势看多开仓')
        return TradeSignal(action='HOLD', price=price)

